INSERT INTO collection_pages VALUES('5634cbbf5ce5e55cfcc19f6b29df6da1dbdc59272d70fd89ca93ebce2f6c89a3','f154fa66bf13518513b0773da75253df0acaa081621bff0c66125320feb980d5','{"hasNext":false,"items":[{"author":{"account":null,"email":"amir.akbari@inrebus.it","name":"AMIRAK-code"},"authoredDate":"2026-06-30T07:20:52Z","committedDate":"2026-06-30T07:20:52Z","committer":{"account":null,"email":"amir.akbari@inrebus.it","name":"AMIRAK-code"},"observedAt":"2026-10-08T22:31:26.194Z","repositoryId":1203751333,"sha":"ea95764d011ad3f66f9ae3223d727ddbb92728a1"}],"observedAt":"2026-10-08T22:31:26.194Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/AMIRAK-code/NUCLEAR-HMI-TWIN/commits/ea95764d011ad3f66f9ae3223d727ddbb92728a1/comments","commit":{"author":{"date":"2026-06-30T07:20:52Z","email":"amir.akbari@inrebus.it","name":"AMIRAK-code"},"comment_count":0,"committer":{"date":"2026-06-30T07:20:52Z","email":"amir.akbari@inrebus.it","name":"AMIRAK-code"},"message":"Add alarm remediation guidance, severity-based notifications, and desktop-packaging ADR\n\n- CMP-47 (SCR-07) alarm detail: \"how to solve it\" suggestion panel + VR\n  training link (when present), plus a \"Storico su questo sensore\" column\n  showing prior occurrences of the event type on that sensor.\n- Severity-based alarm notifications: warnings (P2/P3) stay in the top bar;\n  P1 Critical now renders a blocking, acknowledge-to-close popup that also\n  carries the remediation steps and VR training link.\n- Single guidance source (alarmGuidance) shared by the detail panel and the\n  critical popup; HTML escaped via escHtml.\n- docs/adr/ADR-0001: decision record for packaging as a desktop app with Tauri.\n\nCo-Authored-By: Claude Opus 4.8 <noreply@anthropic.com>","tree":{"sha":"e920733bb795c112df28383323f27dae76a0544a","url":"https://api.github.com/repos/AMIRAK-code/NUCLEAR-HMI-TWIN/git/trees/e920733bb795c112df28383323f27dae76a0544a"},"url":"https://api.github.com/repos/AMIRAK-code/NUCLEAR-HMI-TWIN/gi